let audioCtx;
        let panner;
        let oscillator;
        let gainNode;
        let delayNode;

        function initAudio() {
            if (!audioCtx) {
                audioCtx = new (window.AudioContext || window.webkitAudioContext)();
                panner = audioCtx.createStereoPanner();
                gainNode = audioCtx.createGain();
                panner.connect(gainNode);
                gainNode.connect(audioCtx.destination);
                gainNode.gain.setValueAtTime(0.3, audioCtx.currentTime);
            }
        }

        function stopAudio() {
            if (oscillator) {
                oscillator.stop();
                if (oscillator.disconnect) oscillator.disconnect();
                oscillator = null;
            }
            document.querySelectorAll('.channel-btn').forEach(b => b.classList.remove('pinging'));
            document.getElementById('btn-haas-left').classList.remove('pinging-purple');
            document.getElementById('btn-haas-right').classList.remove('pinging-purple');
        }

        function playChannel(side) {
            initAudio();
            stopAudio();
            oscillator = audioCtx.createOscillator();
            oscillator.type = 'sine';
            oscillator.frequency.setValueAtTime(440, audioCtx.currentTime);
            let panVal = 0;
            if (side === 'left') {
                panVal = -1;
                document.getElementById('btn-left').classList.add('pinging');
            } else if (side === 'right') {
                panVal = 1;
                document.getElementById('btn-right').classList.add('pinging');
            } else {
                panVal = 0;
                document.getElementById('btn-center').classList.add('pinging');
            }
            panner.pan.setValueAtTime(panVal, audioCtx.currentTime);
            oscillator.connect(panner);
            oscillator.start();
        }

        function updatePan(val) {
            initAudio();
            if (panner) panner.pan.setTargetAtTime(val, audioCtx.currentTime, 0.05);
            const label = document.getElementById('pan-label');
            const percent = Math.abs(Math.round(val * 100));
            if (val < -0.1) label.innerText = `${percent}% Left`;
            else if (val > 0.1) label.innerText = `${percent}% Right`;
            else label.innerText = "Center";
        }

        // --- Psychoacoustic ITD Engine ---
        function updateHaasLabel(val) {
            document.getElementById('haas-label').innerText = `${parseFloat(val).toFixed(1)} ms Delay`;
        }

        function playHaas(delaySide) {
            initAudio();
            stopAudio();

            const msDelay = parseFloat(document.getElementById('haas-slider').value);
            const merger = audioCtx.createChannelMerger(2);
            const osc = audioCtx.createOscillator();

            // We use a pulsed/clicking sound instead of a pure sine wave because 
            // the brain calculates time delay significantly better with sharp transients.
            osc.type = 'sawtooth';
            osc.frequency.value = 200;

            // Soften the raw sawtooth so it doesn't hurt ears
            const lowpass = audioCtx.createBiquadFilter();
            lowpass.type = "lowpass";
            lowpass.frequency.value = 1500;
            osc.connect(lowpass);

            // Create delay path
            delayNode = audioCtx.createDelay(1.0);
            delayNode.delayTime.value = msDelay / 1000.0;

            // Both channels get EXACTLY the same volume. Only Time changes.
            if (delaySide === 'left') {
                lowpass.connect(delayNode);
                delayNode.connect(merger, 0, 0); // Left channel delayed
                lowpass.connect(merger, 0, 1);   // Right channel instant
                document.getElementById('btn-haas-left').classList.add('pinging-purple');
            } else {
                lowpass.connect(merger, 0, 0);   // Left channel instant
                lowpass.connect(delayNode);
                delayNode.connect(merger, 0, 1); // Right channel delayed
                document.getElementById('btn-haas-right').classList.add('pinging-purple');
            }

            merger.connect(gainNode);
            osc.start();

            // Custom cleanup object mimicking oscillator API
            oscillator = {
                stop: () => osc.stop(),
                disconnect: () => { osc.disconnect(); lowpass.disconnect(); delayNode.disconnect(); merger.disconnect(); }
            };
        }

        function playPhase(type) {
            initAudio();
            stopAudio();
            const merger = audioCtx.createChannelMerger(2);
            const oscL = audioCtx.createOscillator();
            const oscR = audioCtx.createOscillator();
            const gainR = audioCtx.createGain();
            oscL.frequency.value = 220;
            oscR.frequency.value = 220;

            if (type === 'out') {
                gainR.gain.value = -1; // Phase Inversion logic
            } else {
                gainR.gain.value = 1;
            }

            oscL.connect(merger, 0, 0);
            oscR.connect(gainR);
            gainR.connect(merger, 0, 1);
            merger.connect(gainNode);
            oscL.start();
            oscR.start();

            oscillator = {
                stop: () => { oscL.stop(); oscR.stop(); },
                disconnect: () => { oscL.disconnect(); oscR.disconnect(); merger.disconnect(); }
            };

            // Auto stop after 3s to prevent user ear fatigue during phase inversion
            setTimeout(stopAudio, 3000);
        }

